?>
<main id="primary" class="mmaf-notification-page"><div class="mmaf-notification-card">
<?php if(!Config::feature_enabled()): ?><h1>Notifications are coming soon</h1><p>This feature is currently available only to the staging test group.</p>
<?php elseif(in_array($page,array('login','register'),true)): ?>
	<h1><?php echo 'register'===$page?'Create your account':'Sign in'; ?></h1>
	<p><?php echo $intent['fighter_id']?'Sign in to follow this fighter and receive event updates.':'Use Google or a secure email link. No password is required.'; ?></p>
	<?php if(!empty($_GET['mmaf_error'])):?><div class="mmaf-alert mmaf-alert--error"><?php echo esc_html(wp_unslash($_GET['mmaf_error']));?></div><?php endif;?>
	<div class="mmaf-google-login"><?php echo shortcode_exists('nextend_social_login')?do_shortcode('[nextend_social_login provider="google" redirect="'.esc_attr($intent['return_to']).'"]'):'<p class="mmaf-muted">Google sign-in will appear after Nextend Social Login is configured.</p>'; ?></div>
	<div class="mmaf-separator"><span>or</span></div>
	<form data-mmaf-email-login><label for="mmaf-login-email">Email address</label><input id="mmaf-login-email" type="email" name="email" autocomplete="email" required><input type="hidden" name="fighter_id" value="<?php echo esc_attr((string)$intent['fighter_id']);?>"><input type="hidden" name="return_to" value="<?php echo esc_attr($intent['return_to']);?>"><button type="submit">Send sign-in link</button><p data-mmaf-auth-message aria-live="polite"></p></form>
	<p><a href="<?php echo esc_url(home_url('register'===$page?'/login/':'/register/'));?>"><?php echo 'register'===$page?'Already have an account? Sign in':'New here? Create an account';?></a></p>
<?php elseif('account'===$page): $subscriptions_service=new Subscriptions();$subs=$subscriptions_service->listing(get_current_user_id());$upcoming=$subscriptions_service->upcoming(get_current_user_id());$rem=(new Reminders())->listing(get_current_user_id());$notification_repo=new \MMAF\DataEngine\Services\Notifications\Repository();$local_day=(new DateTimeImmutable('now',new DateTimeZone(Config::timezone(get_current_user_id()))))->format('Y-m-d');$next_send=$notification_repo->user_has_daily_message(get_current_user_id(),$local_day)?$notification_repo->next_local_nine_utc(get_current_user_id(),1):null; ?>
	<h1>Your notifications</h1><p>Manage followed fighters, reminders, timezone and sports email delivery.</p>
	<?php if($next_send):?><div class="mmaf-alert">Today’s email slot has been used. New updates can be sent from <?php echo esc_html(wp_date('M j, H:i',strtotime($next_send.' UTC')));?> UTC.</div><?php endif;?>
	<section><h2>Followed fighters</h2><?php if(!$subs):?><p>You are not following any fighters yet.</p><?php else:?><ul class="mmaf-account-list"><?php foreach($subs as $s):?><li><a href="<?php echo esc_url($s['profile_url']);?>"><?php echo esc_html($s['display_name']);?></a><?php echo Module::button((int)$s['fighter_id'],'Following');?></li><?php endforeach;?></ul><?php endif;?></section>
	<section><h2>Known upcoming fights</h2><?php if(!$upcoming):?><p>No upcoming fights are currently known for the fighters you follow.</p><?php else:?><ul class="mmaf-account-list"><?php foreach($upcoming as $fight): $can_remind=$fight['event_date']>$local_day&&!in_array($fight['event_status'],array('cancelled','postponed'),true);?><li><span><strong><?php echo esc_html($fight['fighter_a_name'].' vs '.$fight['fighter_b_name']);?></strong><br><?php echo esc_html($fight['event_title'].' · '.$fight['event_date']);?></span><?php if($can_remind):?><button type="button" data-mmaf-reminder="<?php echo esc_attr($fight['bout_id']);?>">Remind me</button><?php else:?><span class="mmaf-muted">Reminder unavailable until a new date is confirmed.</span><?php endif;?></li><?php endforeach;?></ul><?php endif;?></section>
	<section><h2>Active reminders</h2><?php if(!$rem):?><p>No active reminders.</p><?php else:?><ul class="mmaf-account-list"><?php foreach($rem as $r):?><li><span><?php echo esc_html($r['fighter_a_name'].' vs '.$r['fighter_b_name'].' · '.$r['event_date']);?></span><button type="button" data-mmaf-reminder-cancel="<?php echo esc_attr($r['bout_id']);?>">Cancel reminder</button></li><?php endforeach;?></ul><?php endif;?></section>
	<section><h2>Email settings</h2><form data-mmaf-settings><label>Timezone <input name="timezone" value="<?php echo esc_attr(Config::timezone(get_current_user_id()));?>" list="mmaf-timezones" required></label><datalist id="mmaf-timezones"><option value="Europe/Belgrade"><option value="Europe/London"><option value="America/New_York"><option value="America/Los_Angeles"><option value="Asia/Tokyo"></datalist><label class="mmaf-checkbox"><input type="checkbox" name="enabled" <?php checked(Config::user_enabled(get_current_user_id()));?>> Receive sports email notifications</label><button type="submit">Save settings</button><p data-mmaf-settings-message aria-live="polite"></p></form></section>
<?php elseif('notification-action'===$page): $purpose=sanitize_key($_GET['purpose']??'');$token=sanitize_text_field(wp_unslash($_GET['token']??''));$row=$purpose&&$token?(new Tokens())->inspect($purpose,$token):null; ?>
	<h1>Confirm notification action</h1>
	<?php if(!empty($_GET['mmaf_notice'])):?><div class="mmaf-alert"><?php echo esc_html(wp_unslash($_GET['mmaf_notice']));?></div><?php elseif(!empty($_GET['mmaf_error'])):?><div class="mmaf-alert mmaf-alert--error"><?php echo esc_html(wp_unslash($_GET['mmaf_error']));?></div><?php elseif($row&&'magic_login'===$purpose):?><p>Confirm this sign-in request. Opening the email link alone does not sign you in.</p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mmaf_magic_confirm"><input type="hidden" name="token" value="<?php echo esc_attr($token);?>"><?php wp_nonce_field('mmaf_magic_confirm');?><button type="submit">Confirm sign in</button></form><?php elseif($row):?><p><?php echo 'reminder'===$purpose?'Confirm that you want a reminder for this fight.':'Confirm that you want to stop all sports notifications and reminders.';?></p><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="mmaf_token_action"><input type="hidden" name="purpose" value="<?php echo esc_attr($purpose);?>"><input type="hidden" name="token" value="<?php echo esc_attr($token);?>"><?php wp_nonce_field('mmaf_token_action');?><button type="submit"><?php echo 'reminder'===$purpose?'Remind me':'Unsubscribe';?></button></form><?php else:?><div class="mmaf-alert mmaf-alert--error">This secure action link is invalid or expired.</div><?php endif;?>
<?php endif; ?>
</div></main>
